type Node struct { Text string; Kids []Node }             // value nodes, no pointer graph
type Frame struct { Left, Right []Node; Parent Node } // siblings around the hole
type Loc struct { Focus Node; Path []Frame }
func Down(l Loc) Loc {                                // descend to the leftmost child
    f := Frame{Right: slices.Clone(l.Focus.Kids[1:]), Parent: l.Focus}
    return Loc{Focus: l.Focus.Kids[0], Path: append(l.Path, f)}
}
func Up(l Loc) Loc {                                  // rebuild the parent, pop the frame
    f := l.Path[len(l.Path)-1]
    kids := append(append(slices.Clone(f.Left), l.Focus), f.Right...)
    return Loc{Focus: Node{f.Parent.Text, kids}, Path: l.Path[:len(l.Path)-1]}
}
